BEGIN;
CREATE TABLE world_intelligence.source_independence_edges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid NOT NULL REFERENCES world_intelligence.sources(id) ON DELETE RESTRICT,related_source_id uuid NOT NULL REFERENCES world_intelligence.sources(id) ON DELETE RESTRICT,relationship text NOT NULL,confidence numeric(5,4) NOT NULL CHECK(confidence BETWEEN 0 AND 1),UNIQUE(source_id,related_source_id),CHECK(source_id<>related_source_id));
CREATE TABLE world_intelligence.anomalies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_ref text NOT NULL,metric text NOT NULL,observed double precision NOT NULL,baseline double precision NOT NULL,score double precision NOT NULL,detected_at timestamptz NOT NULL);
CREATE TABLE world_intelligence.intelligence_cards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,summary text NOT NULL,freshness text NOT NULL,confidence numeric(5,4) NOT NULL CHECK(confidence BETWEEN 0 AND 1),evidence_ids uuid[] NOT NULL DEFAULT '{}',contradiction_ids uuid[] NOT NULL DEFAULT '{}',provenance_ids uuid[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE world_intelligence.intelligence_explanations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intelligence_id uuid NOT NULL REFERENCES world_intelligence.intelligence_cards(id) ON DELETE RESTRICT,rule_id text,change_ids uuid[] NOT NULL DEFAULT '{}',observation_ids uuid[] NOT NULL DEFAULT '{}',evidence_ids uuid[] NOT NULL DEFAULT '{}',artifact_ids uuid[] NOT NULL DEFAULT '{}',source_ids uuid[] NOT NULL DEFAULT '{}');
COMMIT;